class Solution {
    public int longestAlternatingGroups(int[] groups) {
        if (groups.length == 0) {
            return 0;
        }
        int answer = 1;
        for (int i = 1; i < groups.length; i++) {
            if (groups[i] != groups[i - 1]) {
                answer++;
            }
        }
        return answer;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int longestAlternatingGroups(int[] groups) {
        List<Integer> runs = new ArrayList<>();
        for (int group : groups) {
            if (runs.isEmpty() || runs.get(runs.size() - 1) != group) {
                runs.add(group);
            }
        }
        return runs.size();
    }
}

class Solution {
    public int longestAlternatingGroups(int[] groups) {
        int zero = 0;
        int one = 0;
        for (int group : groups) {
            if (group == 0) {
                zero = Math.max(zero, one + 1);
            } else {
                one = Math.max(one, zero + 1);
            }
        }
        return Math.max(zero, one);
    }
}

class Solution {
    public int longestAlternatingGroups(int[] groups) {
        if (groups.length == 0) {
            return 0;
        }
        int[] dp = new int[groups.length];
        java.util.Arrays.fill(dp, 1);
        int best = 1;
        for (int i = 0; i < groups.length; i++) {
            for (int j = 0; j < i; j++) {
                if (groups[i] != groups[j]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    private int[][] memo;
    private int[] groups;

    public int longestAlternatingGroups(int[] groups) {
        this.groups = groups;
        memo = new int[groups.length][3];
        for (int i = 0; i < groups.length; i++) {
            java.util.Arrays.fill(memo[i], -1);
        }
        return dfs(0, 2);
    }

    private int dfs(int index, int previous) {
        if (index == groups.length) {
            return 0;
        }
        if (memo[index][previous] != -1) {
            return memo[index][previous];
        }
        int best = dfs(index + 1, previous);
        if (previous == 2 || groups[index] != previous) {
            best = Math.max(best, 1 + dfs(index + 1, groups[index]));
        }
        memo[index][previous] = best;
        return best;
    }
}
